function PurchasesView({orders,recs,products,suppliers,safe,busy,reload,permitted}:any){
 const [tab,setTab]=useState<'recs'|'orders'>('recs'),[receipt,setReceipt]=useState<Po|null>(null),[expiration,setExpiration]=useState<Record<string,string>>({});
 const ready=recs.filter((r:Rec)=>r.quantity>0&&r.supplier_id);
 async function fromRec(r:Rec){await safe(async()=>{await api('/purchase-orders',{method:'POST',body:JSON.stringify({supplier_id:r.supplier_id,items:[{product_id:r.product_id,quantity:r.quantity}]})});setTab('orders');await reload()})}
 async function approve(id:string){await safe(async()=>{await api(`/purchase-orders/${id}/approve`,{method:'POST'});await reload()})}
 async function receive(){if(!receipt)return;await safe(async()=>{const lineItems=receipt.items.filter(i=>i.quantity>i.received_qty).map(i=>({product_id:i.product_id,quantity:i.quantity-i.received_qty,lot_code:'PO-'+receipt.id.slice(0,8),expires_at:expiration[i.product_id]||null}));if(!lineItems.length)throw Error('Нет позиций к приёмке');await api(`/purchase-orders/${receipt.id}/receive`,{method:'POST',body:JSON.stringify({purchase_order_id:receipt.id,supplier_id:receipt.supplier_id,invoice_number:'PO-'+receipt.id.slice(0,8),items:lineItems,idempotency_key:uuid()})});setReceipt(null);await reload()})}
 return <><Heading title="Интеллектуальные закупки" desc="Обоснованный заказ с кратностью упаковки и учётом поставок" actions={<Pill tone="blue">{ready.length} рекомендаций к закупке</Pill>}/><div className="card mb-5 p-4 flex gap-4 justify-between flex-wrap"><div className="flex gap-2">{(['recs','orders'] as const).map((id,i)=><button key={id} onClick={()=>setTab(id)} className={'btn '+(tab===id?'':'btn-outline')}>{['Рекомендации AI','Заказы поставщикам'][i]}</button>)}</div><button className="btn btn-outline" onClick={()=>safe(reload)}><RefreshCw size={15}/> Пересчитать</button></div>
 {tab==='recs'?<div className="grid gap-4">{recs.filter((r:Rec)=>r.quantity>0).slice(0,40).map((r:Rec)=><div className="card p-5 grid gap-5 lg:grid-cols-[1fr_auto] lg:items-center" key={r.product_id}><div><div className="flex flex-wrap items-center gap-3"><div className="font-bold text-[14px]">{r.name}</div><Pill tone={r.urgency==='Срочно'?'red':'amber'}>{r.urgency}</Pill><Pill>{r.certainty} уверенность</Pill></div><div className="text-[11px] text-slate-500 mt-2">{r.supplier_name||'Поставщик не привязан'} · Срок доставки {r.lead_time_days} дн.</div><div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mt-4">{[['Остаток',num(r.stock)],['Спрос / день',num(r.daily_demand,2)],['Страховой запас',num(r.safety_stock)],['Позиция',num(r.inventory_position)]].map(([k,v])=><div className="bg-slate-50 rounded-lg p-3" key={k}><div className="text-[10px] text-slate-400 mb-1">{k}</div><div className="font-bold text-sm">{v}</div></div>)}</div><details className="mt-3 text-[11px] text-slate-600"><summary className="cursor-pointer text-blue-600 font-semibold">Почему именно столько?</summary><div className="mt-2 bg-blue-50 rounded-lg p-3 leading-5">{r.reason}{r.constraints?.length?` Ограничения: ${r.constraints.join(', ')}.`:''}</div></details></div><div className="lg:text-right"><div className="text-[11px] muted">Рекомендовано</div><div className="text-2xl font-extrabold tracking-tight my-1">{num(r.quantity)} шт.</div><div className="font-semibold text-slate-500 text-sm mb-4">{cash(r.estimated_cost)}</div><button disabled={busy||!r.supplier_id||!permitted(ownerManager)} className="btn" onClick={()=>fromRec(r)}><Plus size={15}/> Создать заказ</button></div></div>)}{!ready.length&&<div className="empty card">Заказов на пополнение нет</div>}</div>:
 <Panel title="Заказы поставщикам" desc="Черновик → утверждён → получен / частично получен"><Table heads={['Заказ','Дата','Поставщик','Сумма','Статус','Действия']}>{orders.map((o:Po)=><tr key={o.id}><td className="font-mono">#{o.id.slice(0,8)}</td><td>{dt(o.created_at)}</td><td>{suppliers.find((s:Supplier)=>s.id===o.supplier_id)?.name}</td><td className="font-bold">{cash(o.total)}</td><td><Pill tone={o.status==='received'?'green':o.status==='draft'?'amber':'blue'}>{({draft:'Черновик',approved:'Утверждён',ordered:'Заказан',partial_received:'Частично получен',received:'Получен'})[o.status as 'draft']||o.status}</Pill></td><td><div className="flex gap-2">{o.status==='draft'&&permitted(ownerManager)&&<button className="btn btn-outline !py-2" disabled={busy} onClick={()=>approve(o.id)}>Утвердить</button>}{['approved','partial_received','ordered'].includes(o.status)&&<button className="btn btn-teal !py-2" onClick={()=>{setReceipt(o);setExpiration({})}}>Принять</button>}</div></td></tr>)}</Table>{!orders.length&&<div className="empty">Заказов ещё нет. Создайте из рекомендаций.</div>}</Panel>}
 {receipt&&<Pop title={'Приёмка заказа #'+receipt.id.slice(0,8)} close={()=>setReceipt(null)} footer={<><button className="btn btn-outline" onClick={()=>setReceipt(null)}>Отмена</button><button className="btn btn-teal" disabled={busy} onClick={receive}>Подтвердить поставку</button></>}><div className="space-y-3">{receipt.items.map(i=><div className="border border-slate-200 rounded-xl p-4" key={i.product_id}><div className="font-semibold mb-1">{products.find((p:Product)=>p.id===i.product_id)?.name}</div><div className="text-xs muted mb-3">Заказано: {i.quantity} · Получено: {i.received_qty} · К получению: {i.quantity-i.received_qty}</div><Field label="Срок годности партии (необязательно)"><input type="date" className="input" value={expiration[i.product_id]||''} onChange={e=>setExpiration(p=>({...p,[i.product_id]:e.target.value}))}/></Field></div>)}</div></Pop>}</>
}

function ForecastView({products}:any){
 const [selected,setSelected]=useState(''),[data,setData]=useState<any>(null),[days,setDays]=useState(14),[pending,setPending]=useState(false);
 useEffect(()=>{if(products.length&&!selected)setSelected(products[0].id)},[products]);
 useEffect(()=>{if(!selected)return;setPending(true);api('/forecast/'+selected).then(setData).catch(()=>setData(null)).finally(()=>setPending(false))},[selected]);
 const p=products.find((p:Product)=>p.id===selected);const shown=data?.series?.slice(0,days)||[];
 return <><Heading title="Прогноз спроса" desc="Baseline прогноз по истории продаж · Объяснимые расчёты и реальные метрики backtest" actions={<Pill tone="amber">Не нейросеть / не LLM</Pill>}/><Panel title="Параметры прогноза" className="mb-5"><div className="p-5 grid sm:grid-cols-2 gap-4"><Field label="Товар"><select className="input" value={selected} onChange={e=>setSelected(e.target.value)}>{products.map((x:Product)=><option key={x.id} value={x.id}>{x.name} — {x.sku}</option>)}</select></Field><Field label="Горизонт прогноза"><select className="input" value={days} onChange={e=>setDays(Number(e.target.value))}><option value={7}>7 дней</option><option value={14}>14 дней</option><option value={30}>30 дней</option></select></Field></div></Panel>
 {data?<><div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-5">{[['Прогноз / день',num(data.rate,2)+' ед.'],['Дней данных',String(data.valid_days)],['MAE, ед.',data.mae_units===null?'Недоступно':num(data.mae_units,2)],['WAPE backtest',data.wape_percent===null?'Недоступно':num(data.wape_percent,1)+'%']].map(([label,v])=><div key={label} className="card p-5"><div className="stat-title">{label}</div><div className="stat-value !text-xl">{v}</div></div>)}</div>
 <Panel title={`Прогноз · ${p?.name||''}`} desc={`${days} дней · Сплошная линия — ожидание, пунктир — верхняя/нижняя границы`} actions={<Pill tone="blue">{data.model_type}</Pill>}><div className="h-[340px] p-5"><ResponsiveContainer width="100%" height="100%"><LineChart data={shown}><CartesianGrid stroke="#e7edf5" strokeDasharray="3 3" vertical={false}/><XAxis dataKey="date" tickFormatter={(s:string)=>s.slice(5).split('-').reverse().join('.')} tickLine={false} axisLine={false} fontSize={10}/><YAxis tickLine={false} axisLine={false} fontSize={10}/><Tooltip/><Legend/><Line type="monotone" dataKey="expected" stroke="#2563eb" strokeWidth={3} name="Ожидаемый спрос" dot={false}/><Line type="monotone" dataKey="low" stroke="#0d9488" strokeDasharray="5 5" name="Нижняя граница" dot={false}/><Line type="monotone" dataKey="high" stroke="#f59e0b" strokeDasharray="5 5" name="Верхняя граница" dot={false}/></LineChart></ResponsiveContainer></div></Panel>
 <div className="card p-5 mt-5"><div className="font-bold mb-3 flex items-center gap-2"><Lightbulb size={17} className="text-blue-600"/> Почему такой прогноз?</div><p className="leading-6 text-slate-600">{data.explanation}</p><div className="flex flex-wrap gap-2 mt-4"><Pill>Качество данных: {data.data_quality}</Pill><Pill>Пропущено stockout дней: {data.excluded_stockout_days}</Pill>{data.synthetic_history&&<Pill tone="amber">История синтетическая DEMO</Pill>}</div></div></>:<div className="empty card">{pending?'Считаем прогноз…':'Выберите товар для построения прогноза'}</div>}</>
}

function TwinView({recs}:any){
 const [budget,setBudget]=useState('150000'),[horizon,setHorizon]=useState(14),[factor,setFactor]=useState(1),[data,setData]=useState<any>(null),[pending,setPending]=useState(false),[error,setError]=useState('');const [custom,setCustom]=useState<Record<string,string>>({}),[manual,setManual]=useState(false);
 async function simulate(){setPending(true);setError('');try{const body:any={budget:Number(budget),horizon,demand_factor:factor};if(manual)body.custom=Object.fromEntries(Object.entries(custom).filter(([,v])=>v!=='').map(([id,v])=>[id,Number(v)]));setData(await api('/decision-twin/simulate',{method:'POST',body:JSON.stringify(body)}))}catch(e:any){setError(e.message)}finally{setPending(false)}}
 useEffect(()=>{simulate()},[]);
 const sc=data?.scenarios||[];
 const comparison=sc.map((x:any)=>({name:x.name,profit:x.gross_profit,loss:x.lost_gross_margin,stock:x.stock_value}));
 return <><Heading title="Digital Twin — цифровой двойник" desc="Смоделируйте будущее магазина до размещения заказа" actions={<Pill tone="blue"><Layers3 size={13}/> Что будет, если…?</Pill>}/><div className="card p-6 mb-5"><div className="flex gap-3 items-start"><div className="p-3 bg-blue-50 text-blue-600 rounded-xl"><Lightbulb size={21}/></div><div><h2 className="font-bold text-[15px]">Принятие решений на основе сценариев</h2><p className="text-slate-500 text-xs mt-2 leading-6">Модель день за днём рассчитывает спрос, поставки, доступные партии, потери продаж и валовую прибыль. Это приблизительная бизнес-симуляция — не обещание точной выручки.</p></div></div></div>
 <Panel title="Настройки симуляции" className="mb-5"><div className="p-5 grid sm:grid-cols-3 gap-4"><Field label="Бюджет на закупку, ₸"><input className="input" type="number" min="0" step="1000" value={budget} onChange={e=>setBudget(e.target.value)}/></Field><Field label="Период"><select className="input" value={horizon} onChange={e=>setHorizon(Number(e.target.value))}><option value={7}>7 дней</option><option value={14}>14 дней</option><option value={30}>30 дней</option></select></Field><Field label="Коэффициент спроса"><select className="input" value={factor} onChange={e=>setFactor(Number(e.target.value))}><option value={.8}>−20% спрос</option><option value={1}>Базовый спрос</option><option value={1.2}>+20% спрос</option></select></Field></div><div className="px-5 pb-5 flex gap-4 flex-wrap items-center"><button className="btn" disabled={pending} onClick={simulate}><Play size={15}/>{pending?'Симуляция…':'Рассчитать сценарии'}</button><label className="flex items-center gap-2 cursor-pointer font-semibold"><input type="checkbox" checked={manual} onChange={e=>setManual(e.target.checked)}/> Ручные количества</label></div>{manual&&<div className="px-5 pb-5"><div className="text-xs muted mb-2">Заполните количества для выбранных SKU. Неуказанные товары не заказываются.</div><div className="grid sm:grid-cols-2 xl:grid-cols-3 gap-3">{recs.filter((r:Rec)=>r.supplier_id).slice(0,15).map((r:Rec)=><div key={r.product_id}><Field label={`${r.name} · пак. ${r.pack_multiple}`}><input className="input" type="number" min="0" step={r.pack_multiple} value={custom[r.product_id]||''} placeholder={`Рекомендация: ${r.quantity}`} onChange={e=>setCustom(prev=>({...prev,[r.product_id]:e.target.value}))}/></Field></div>)}</div></div>}</Panel>{error&&<div className="tag tag-red mb-5 w-full p-4">{error}</div>}
 {sc.length>0&&<><div className="grid md:grid-cols-3 gap-4 mb-5">{sc.map((s:any,i:number)=><div key={s.key} className={`card overflow-hidden ${i===2?'ring-2 ring-blue-500':''}`}><div className={i===2?'accent-line':'h-[3px] bg-slate-200'}/><div className="p-5"><div className="flex justify-between gap-2"><h3 className="font-bold text-[14px]">{s.name}</h3>{i===2&&<Pill tone="blue">Ваш бюджет</Pill>}</div><div className="muted text-[11px] mt-3">Оценка валовой прибыли</div><div className="text-2xl font-extrabold tracking-tight mt-1">{cash(s.gross_profit)}</div><div className="grid grid-cols-2 gap-3 mt-5">{[['Недополученная маржа',cash(s.lost_gross_margin)],['Потрачено на закупку',cash(s.purchase_spend)],['Дефицит, ед.',num(s.lost_units,1)],['Капитал на остатках',cash(s.stock_value)]].map(([k,v])=><div key={k}><div className="text-[10px] text-slate-400 mb-1">{k}</div><div className="text-[12px] font-bold">{v}</div></div>)}</div></div></div>)}</div>
 <div className="grid xl:grid-cols-2 gap-5 mb-5"><Panel title="Сравнение валовой прибыли" desc="₸, без операционных расходов"><div className="h-[290px] p-5"><ResponsiveContainer width="100%" height="100%"><BarChart data={comparison}><CartesianGrid vertical={false} stroke="#e6edf5" strokeDasharray="4 4"/><XAxis dataKey="name" tick={{fontSize:10}} tickLine={false}/><YAxis tickFormatter={(v:number)=>String(Math.round(v/1000))+'k'} tick={{fontSize:10}} tickLine={false}/><Tooltip formatter={(v:any)=>cash(v)}/><Bar dataKey="profit" name="Валовая прибыль" fill="#2563eb" radius={[5,5,0,0]}/></BarChart></ResponsiveContainer></div></Panel>
 <Panel title="Ожидаемая потеря маржи" desc="Потенциальный спрос, не покрытый запасом"><div className="h-[290px] p-5"><ResponsiveContainer width="100%" height="100%"><BarChart data={comparison}><CartesianGrid vertical={false} stroke="#e6edf5" strokeDasharray="4 4"/><XAxis dataKey="name" tick={{fontSize:10}} tickLine={false}/><YAxis tickFormatter={(v:number)=>String(Math.round(v/1000))+'k'} tick={{fontSize:10}} tickLine={false}/><Tooltip formatter={(v:any)=>cash(v)}/><Bar dataKey="loss" name="Недополученная маржа" fill="#f59e0b" radius={[5,5,0,0]}/></BarChart></ResponsiveContainer></div></Panel></div>
 <Panel title="Чувствительность к спросу ±20%" desc="Дефицит в единицах при пессимистичном / оптимистичном спросе"><Table heads={['Сценарий','Спрос −20%: дефицит','Спрос +20%: дефицит']}>{sc.map((s:any)=><tr key={s.key}><td className="font-semibold">{s.name}</td><td>{num(data.sensitivity_lost_units[s.key].low,1)}</td><td>{num(data.sensitivity_lost_units[s.key].high,1)}</td></tr>)}</Table></Panel>
 <div className="card p-5 mt-5"><div className="font-bold mb-2">Предпосылки и ограничения</div><p className="text-xs text-slate-500 leading-6">{data.assumptions.method}. {data.assumptions.limitations}. Продажи ограничены фактическим запасом, партии с истёкшей датой исключаются, поступления — через срок доставки поставщика. «Рекомендованный заказ» не ограничен бюджетом; третий сценарий — ограничен. Синтетические данные DEMO.</p></div></>}
 </>
}

function SuppliersView({suppliers,safe,busy,reload,permitted}:any){
 const [modal,setModal]=useState(false),[form,setForm]=useState({name:'',phone:'',lead_time_days:3});
 return <><Heading title="Поставщики" desc="Справочник партнёров, контакты и сроки доставки" actions={permitted(ownerManager)&&<button className="btn" onClick={()=>setModal(true)}><Plus size={16}/> Новый поставщик</button>}/><div className="grid sm:grid-cols-2 xl:grid-cols-3 gap-4">{suppliers.map((s:Supplier)=><div className="card p-5" key={s.id}><div className="flex gap-4"><div className="h-11 w-11 rounded-xl bg-blue-50 text-blue-600 grid place-items-center"><Truck size={21}/></div><div><div className="font-bold text-sm">{s.name}</div><p className="muted mt-2">{s.phone}</p></div></div><div className="mt-6 flex gap-2 items-center"><Pill tone="blue"><Clock3 size={13}/> Доставка {s.lead_time_days} дней</Pill><Pill tone="green">Активен</Pill></div></div>)}</div>{modal&&<Pop title="Новый поставщик" close={()=>setModal(false)} footer={<><button className="btn btn-outline" onClick={()=>setModal(false)}>Отмена</button><button className="btn" disabled={busy} onClick={()=>safe(async()=>{await api('/suppliers',{method:'POST',body:JSON.stringify(form)});setModal(false);await reload()})}>Создать</button></>}><div className="space-y-4"><Field label="Название компании"><input className="input" value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></Field><Field label="Телефон"><input className="input" value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})}/></Field><Field label="Доставка, дней"><input className="input" type="number" min="0" value={form.lead_time_days} onChange={e=>setForm({...form,lead_time_days:Number(e.target.value)})}/></Field></div></Pop>}</>
}

function AssistantView(){
 const suggestions=['Что скоро закончится?','На что потратить 150000 ₸?','Почему система предложила заказать молоко?','Какие товары скоро испортятся?'];
 const [question,setQuestion]=useState(''),[messages,setMessages]=useState<{from:'you'|'ai',text:string}[]>([{from:'ai',text:'Здравствуйте! Я локальный аналитический ассистент. Задайте вопрос об остатках, закупках, бюджете или сроках годности. Все числа беру из расчётного движка, а не из внешней языковой модели.'}]),[loading,setLoading]=useState(false);const scroll=useRef<HTMLDivElement>(null);
 async function ask(q=question){if(!q.trim())return;setMessages(prev=>[...prev,{from:'you',text:q}]);setQuestion('');setLoading(true);try{const result=await api('/assistant/ask',{method:'POST',body:JSON.stringify({question:q})});setMessages(prev=>[...prev,{from:'ai',text:result.answer}])}catch(e:any){setMessages(prev=>[...prev,{from:'ai',text:'Ошибка: '+e.message}])}finally{setLoading(false);setTimeout(()=>scroll.current?.scrollIntoView({behavior:'smooth'}),80)}}
 return <><Heading title="Аналитический ассистент" desc="Запросы на естественном языке → факты из базы → объяснимый результат" actions={<Pill tone="green"><ShieldCheck size={12}/> Локальный deterministic engine</Pill>}/><div className="card max-w-4xl mx-auto overflow-hidden"><div className="p-5 border-b border-slate-100"><div className="flex gap-3 items-center"><div className="p-2.5 rounded-xl bg-blue-600 text-white"><MessageSquareText size={19}/></div><div><div className="font-bold">Smart AI Assistant</div><div className="text-[11px] text-slate-500">Без подключения к ChatGPT/LLM · DEMO data</div></div></div></div><div className="h-[460px] overflow-y-auto p-5 space-y-4 bg-slate-50/60">{messages.map((msg,i)=><div key={i} className={'flex '+(msg.from==='you'?'justify-end':'justify-start')}><div className={'p-4 rounded-2xl max-w-[85%] text-[12px] whitespace-pre-wrap leading-6 '+(msg.from==='you'?'bg-blue-600 text-white rounded-br-sm':'bg-white border border-slate-200 rounded-bl-sm shadow-sm')}>{msg.text}</div></div>)}{loading&&<div className="text-slate-400 text-xs">Анализируем данные магазина…</div>}<div ref={scroll}/></div><div className="p-5 border-t border-slate-100"><div className="flex gap-2 overflow-x-auto pb-4">{suggestions.map(x=><button key={x} onClick={()=>ask(x)} className="btn btn-outline !py-2 !text-[10px]">{x}</button>)}</div><form onSubmit={e=>{e.preventDefault();ask()}} className="flex gap-2"><input className="input !py-3" value={question} onChange={e=>setQuestion(e.target.value)} placeholder="Спросите, например: «На что потратить 90000 тенге?»"/><button className="btn" disabled={loading||!question.trim()}><ArrowRight size={18}/></button></form></div></div></>
}

function SettingsView({user,audits,safe,busy,reload,router}:any){
 const [importKind,setImportKind]=useState<'products'|'sales'>('products'),[file,setFile]=useState<File|null>(null),[confirmReset,setConfirmReset]=useState(false);
 async function importCsv(){if(!file)return;await safe(async()=>{const data=new FormData();data.append('file',file);await api('/imports/'+(importKind==='products'?'products-csv':'sales-csv'),{method:'POST',body:data});setFile(null);await reload()})}
 return <><Heading title="Настройки системы" desc="Профиль, CSV-импорт, аудит и управление демо-данными"/><div className="grid xl:grid-cols-2 gap-5"><Panel title="Профиль и доступ"><div className="p-5"><div className="flex items-center gap-4 mb-6"><div className="w-14 h-14 rounded-xl bg-blue-100 text-blue-700 text-xl font-bold grid place-items-center">{user.name[0]}</div><div><div className="font-bold text-[15px]">{user.name}</div><div className="muted mt-1">{user.email}</div></div></div><div className="border-t border-slate-100 pt-4 space-y-3">{[['Роль',user.role],['Валюта','KZT (₸)'],['Дата','DD.MM.YYYY'],['Часовой пояс','Asia/Almaty'],['Язык интерфейса','Русский (RU)']].map(([k,v])=><div className="flex justify-between" key={k}><span className="muted">{k}</span><span className="font-semibold">{v}</span></div>)}</div><p className="mt-5 text-[11px] muted">Архитектура допускает казахскую локализацию. Переключатель KZ появится после перевода словаря интерфейса.</p></div></Panel>
 <Panel title="Импорт CSV" desc="Повторный импорт идентичного файла не создаёт дубликатов"><div className="p-5 space-y-4"><Field label="Тип импорта"><select className="input" value={importKind} onChange={e=>setImportKind(e.target.value as 'products'|'sales')}><option value="products">Каталог новых товаров</option><option value="sales">Исторический спрос (не fiscal POS)</option></select></Field><div className="bg-slate-50 border border-dashed border-slate-300 p-5 rounded-xl text-center"><Upload className="text-slate-400 mx-auto mb-3"/><input type="file" accept=".csv,text/csv" onChange={e=>setFile(e.target.files?.[0]||null)} className="max-w-full text-xs"/></div><p className="text-[11px] muted">{importKind==='products'?'CSV заголовки: sku,barcode,name,category,cost,price':'CSV заголовки: sku,date,quantity,stockout (date в формате YYYY-MM-DD)'}. UTF-8, максимум 2 МБ / 2000 строк.</p><button className="btn" disabled={!file||busy} onClick={importCsv}><Upload size={15}/> Импортировать</button></div></Panel>
 <Panel title="Журнал аудита" desc="Последние подтверждённые операции"><div className="max-h-[380px] overflow-y-auto divide-y divide-slate-100">{audits.map((a:any,i:number)=><div className="p-4 flex items-start gap-3" key={i}><div className="bg-slate-100 rounded-lg p-2"><FileText size={17}/></div><div className="flex-1"><div className="font-semibold">{a.action}</div><div className="muted mt-1 truncate max-w-[300px]">{a.details}</div></div><div className="muted text-[10px]">{dt(a.occurred_at)}</div></div>)}{!audits.length&&<div className="empty">Аудит пока пуст</div>}</div></Panel>
 <Panel title="Демонстрационный режим" desc="Функция доступна только владельцу"><div className="p-5"><div className="p-4 border rounded-xl bg-amber-50 border-amber-100 flex gap-3 items-start"><AlertTriangle size={22} className="text-amber-600 shrink-0"/><div><div className="font-semibold text-amber-800">Сброс демонстрационных данных</div><p className="text-[11px] leading-5 text-amber-700 mt-1">Удаляет все созданные продажи, поставки и товары, восстанавливает 60 исходных позиций и 90 дней синтетического спроса. Это необратимо.</p></div></div><button className="btn btn-outline mt-5" onClick={()=>setConfirmReset(true)}>Сбросить демо-базу</button><p className="text-[11px] muted mt-5">Внешние интеграции 1С, UMAG, фискальная ККМ, Kaspi API, электронная маркировка в демонстрации отсутствуют.</p></div></Panel></div>
 {confirmReset&&<Pop title="Подтверждение сброса" close={()=>setConfirmReset(false)} footer={<><button className="btn btn-outline" onClick={()=>setConfirmReset(false)}>Отмена</button><button className="btn !bg-red-600" disabled={busy} onClick={()=>safe(async()=>{await api('/settings/reset-demo',{method:'POST'});setConfirmReset(false);router.replace('/login')})}>Удалить и восстановить DEMO</button></>}><p className="text-slate-600 leading-6">Все изменения в демонстрационной базе будут безвозвратно удалены. Для реального магазина эту функцию необходимо отключить.</p></Pop>}</>
}
